          "link": "https://arxiv.org/abs/2605.00237",
          "code": null,
          "abstract": "Bayesian optimization is a sequential method for minimizing expensive objective functions. However, standard BO suffers from cubic computational complexity and globally modeling the objective is not optimal for local minimization. Using flexible recursive binary partitioning of the search space, this work adapts both modeling and acquisition to work with the partitioning, yielding linear computational complexity while achieving superior optimization performance on test functions from 6 to 124 dimensions.",
          "rank": 1,
          "core_work": "本文提出了一种基于递归二分搜索空间的贝叶斯优化方法，将建模和采集策略与空间划分协调一致，实现了线性时间复杂度，同时在高维测试函数上超越了标准BO。",
          "contributions": "提出递归二分空间划分与BO的协同框架；实现训练集大小上线性计算复杂度；在6至124维的7个挑战性测试函数上验证超越标准BO库。",
          "innovation": "将搜索空间的递归划分与BO的建模和采集策略深度融合，既解决了标准GP-BO的立方复杂度瓶颈，又通过局部建模改善了全局建模对局部优化不利的缺陷。",
          "relevance": "与您偏好高度相关：Bayesian Optimization + Gaussian Process + 序贯设计。线性复杂度是BO领域的重要突破，对大规模昂贵优化问题具有重要意义。",
          "citations": 0,
          "venue_tier": "Preprint",
          "images": [
            "1_bayesian_optimization_linear_time_x1.png",
            "1_bayesian_optimization_linear_time_x2.png"
          ],
          "content": [
            "贝叶斯优化（BO）是一种序贯优化昂贵评估目标函数的方法，但标准BO存在两个关键问题：（1）训练集规模的立方计算复杂度导致大规模训练不可行；（2）全局建模目标函数对局部最小化并非最优。",
            "**核心贡献**：本文提出了一种基于递归二分搜索空间的BO框架。通过灵活且递归的二分划分，同时调整建模和采集策略以适应划分方案，从而改善了两个标准缺陷。在7个挑战性测试函数（维度6至124）上，该方法在所有测试中均优于常用BO库，且计算复杂度为线性。",
            "**创新之处**：将空间划分与BO的建模和采集深度融合，而非简单地在每个划分区域独立运行BO。这种协同设计使得模型可以在局部区域内进行更精细的建模，同时采集策略能够自适应地在全局探索和局部利用之间切换。",
            "**与您偏好关联**：直接匹配Bayesian Optimization + Gaussian Process + 序贯设计核心方向。线性复杂度的突破对实际应用中的大规模BO问题具有重要意义。"
          ]
