          "code": null,
          "abstract": "Causal Bayesian optimization uses a known causal graph with observational data to decide which variables are worth intervening on. Existing methods learn the effect of each intervention almost in isolation. We propose graph-coupled causal BO, which ties different intervention effects together through uncertainty about a small set of shared causal parameters. For identifiable linear Gaussian causal models, the causal kernel has low rank bounded by the number of shared parameters, yielding an information-gain bound that grows only logarithmically in the optimization horizon, and a regret bound that cleanly separates optimization, causal estimation, and intervention choice errors.",
