          "innovation": "首次通过共享因果参数的低秩因果核实现跨干预信息传递，打破了现有方法孤立学习每个干预效果的局限。",
          "relevance": "与您偏好高度相关：Bayesian Optimization + Gaussian Process + 因果推断。因果BO是结合领域结构知识引导自适应优化的前沿方向。",
          "citations": 0,
          "venue_tier": "Preprint",
