          "code": null,
          "abstract": "Standard BO may require prohibitively many experiments for high-dimensional nonlinear systems. This work presents a hybrid model-based BO that combines iterative Bayesian learning with partially known mechanistic physical models. Instead of learning a direct input-to-objective mapping, all known physics equations are written and GP infers expressions for missing variables. The GP is included as a constraint in the hybrid model, yielding a constrained nonlinear stochastic program. In a single-stage distillation optimization, the hybrid BO converges in as few as one iteration while standard BO does not converge within 25 iterations for any seed.",
