          "date": "2026-07",
          "tags": "Uncertainty Quantification, Conformal Prediction, Time Series, Adaptive Sampling, Bootstrap, Dependence-Aware",
          "link": "https://arxiv.org/abs/2607.06690",
          "code": "https://github.com/sktime/tsbootstrap",
          "abstract": "Finance, sensing, and demand streams violate the exchangeability assumed by IID conformal prediction and bootstrap. tsbootstrap provides block, residual, sieve, and wild resampling, classical bootstrap confidence intervals, and adaptive conformal calibrators (EnbPI, ACI, NexCP, AgACI) through a single typed API. In controlled coverage studies, IID bootstrap undercovers sharply under dependence; dependence-aware methods reduce the coverage deficit. A compiled backend runs several times faster than arch, with streaming reduce limiting peak memory to O(B).",
