          "code": null,
          "abstract": "We introduce a physics-informed Bayesian active learning framework that autonomously tunes precursor pulse times by integrating a Langmuir adsorption model directly into the GP kernel. A key innovation is a two-stage parameter estimation strategy that decouples noise filtering from physical parameter extraction: the GP first smooths noisy data through standard prediction, then Langmuir parameters are fitted to the noise-filtered GP predictions. Convergence within five iterations, up to fourfold improvement in prediction accuracy, and two to fourfold reduction in precursor usage are demonstrated. Experimental validation using TiO2 deposition confirms accurate identification of saturation times for high-coverage targets.",
