          "contributions": "梳理复合材料多层级（组分-铺层-层合板-结构-制造工艺）建模中的多保真度数据融合框架；统一比较GP/Kriging类与深度学习类多保真度方法的假设、成本与精度特性；给出面向复合材料设计、优化与不确定性量化的方法选型指导。",
          "innovation": "以复合材料力学的层级耦合特性为主线，将统计类（co-Kriging/自回归GP）与机器学习类（深度GP、多保真度NN）方法置于同一框架下对比，是该交叉领域少见的系统性综述。",
