          "core_work": "本文系统研究贝叶斯优化与主动学习中的初始化问题：指出常用的（拟）随机空间填充设计忽视了两个关键因素——空间填充未必最利于降低预测不确定性，且初始化阶段的超参数学习与空间填充目标存在冲突；据此提出兼顾预测不确定性降低与超参数学习的知情初始化策略。NeurIPS 2025接收。",
