          "tags": "Bayesian Experimental Design, Gaussian Process, Hierarchical Bayes, Information-Theoretic Sampling, Hyperparameter Uncertainty",
          "link": "https://arxiv.org/abs/2511.16815",
          "code": null,
          "abstract": "We introduce Bayesian Information-Theoretic Sampling for hierarchical GAussian Process Surrogates (BITS for GAPS), a framework enabling information-theoretic experimental design of Gaussian process-based surrogate models. Unlike standard methods, which use fixed or point-estimated hyperparameters in acquisition functions, our approach propagates hyperparameter uncertainty into the sampling criterion through Bayesian hierarchical modeling. In this framework, a latent function receives a Gaussian process prior, while hyperparameters are assigned additional priors to capture the modeler's knowledge of the governing physical phenomena. Consequently, the acquisition function incorporates uncertainties from both the latent function and its hyperparameters, ensuring that sampling is guided by both data scarcity and model uncertainty. We further establish theoretical results in this context.",
          "rank": 7,
          "core_work": "本文提出BITS for GAPS框架：通过贝叶斯层级建模将GP超参数不确定性传播到信息论采样准则中——潜函数赋予GP先验，超参数再赋予反映物理知识的先验，使采集函数同时计入潜函数与超参数两个层级的不确定性，实现由数据稀缺与模型不确定性共同引导的序贯试验设计。发表于Computers & Chemical Engineering 2026。",
