          "tags": "Function-on-Function, Gaussian Process, Emulator, Stochastic Dynamical System, Reliability Analysis, PCA",
          "link": "https://arxiv.org/abs/2602.01929",
          "code": null,
          "abstract": "Constructing accurate and computationally efficient surrogate models (or emulators) for predicting dynamical system responses is critical in many engineering domains, yet remains challenging due to the strongly nonlinear and high-dimensional mapping from external excitations and system parameters to system responses. This work introduces a novel Function-on-Function Nonlinear AutoRegressive model with eXogenous inputs (F2NARX), which reformulates the recently proposed F-NARX method from a function-on-function regression perspective. The proposed framework substantially improves predictive efficiency while maintaining high accuracy. By combining principal component analysis with Gaussian process regression, F2NARX further enables probabilistic predictions of dynamical responses via the unscented transform in an autoregressive manner. Such probabilistic prediction capabilities support reliability analysis of stochastic dynamical systems.",
