          "link": "https://arxiv.org/abs/2607.07289",
          "abstract": "This study presents a multi-fidelity framework for the systematic optimization of genetic algorithm (GA) hyperparameters. The framework integrates three fidelity levels: high-fidelity FFT homogenization for validation, a medium-fidelity 3D CNN surrogate for rapid property evaluation, and a low-fidelity GP surrogate within a BO framework to guide the hyperparameter search. Various acquisition functions are evaluated, with logNEI achieving the best performance. The framework identifies GA configurations enabling a 25-generation run to match full 75-generation optimization quality."
