          "abstract": "Heterotopic sampling (related outputs observed at different input locations) is common in multi-fidelity computer models. Whether joint multivariate kriging predicts better than separate univariate metamodels has remained unresolved. For separable multi-output GPs, the authors show the answer is governed by the geometry of output-specific designs, introduce model-free diagnostics (directed coverage, directed proximity, borrowing potential), and derive an exact identity for the oracle prediction gain of joint modeling."
