          "abstract": "Physics-informed GP regression returns a posterior over PDE solutions, but operator-conditioned formulations have been developed almost exclusively for real-valued fields. The authors extend operator-informed GP regression to complex-valued Helmholtz problems by realifying the complex operator into a coupled real block, admitting priors from proper diagonal to coregionalized and multiscale variants, conditioning on PDE residuals and boundary traces, validated on 1D-3D benchmarks and experimental data."
