          "core_work": "本文提出了一种用于高维约束黑盒优化的信赖域贝叶斯优化方法。在高维设置下，标准BO因代理模型在整个域上的精度下降和采集函数优化困难而表现不佳。约束的存在进一步缩小了可行域，使得搜索更具挑战性。本文方法通过信赖域策略将搜索限制在局部区域，并设计了惩罚约束处理机制。",
