          "core_work": "本文提出了深度跳跃高斯过程（DJGP），一种用于高维分段连续函数代理建模的新方法。传统跳跃高斯过程（JGP）在高维输入空间中受限，而DJGP通过集成区域特定的局部线性投影与JGP建模，解决了这一问题。投影矩阵上放置GP先验以控制模型复杂度，并开发了可扩展的变分推断算法。",
