          "core_work": "本文提供了一个基于代理模型的贝叶斯推断的统一框架，涵盖代理模型训练、不确定性传播和主动学习三个核心组件。框架采用模块化设计，将仿真器预测分布和参数后验的学习分为两个独立步骤，提高了对似然函数误设的鲁棒性。同时，框架提供了多种主动学习策略用于序贯优化实验设计。",
          "contributions": "提出模块化代理模型贝叶斯推断框架；系统综述不确定性传播方法及其权衡；提供目标导向采集函数、迭代采样、温度策略和MCMC引导设计等多种主动学习策略；为科学计算中的昂贵仿真推断提供实用指南。",
          "innovation": "将代理模型的训练、不确定性传播和主动学习整合为统一的模块化工作流。特别是，通过温度策略（Tempering Strategies）逐步从先验过渡到后验，解决了早期代理模型近似差导致采集函数低效的问题。",
