          "core_work": "本文针对数据驱动代理模型缺乏可靠不确定性量化的问题，提出用保形预测（Conformal Prediction）替代传统贝叶斯方法为代理模型提供统计上有效的预测区间。与贝叶斯 GP 需要强分布假设不同，保形预测仅需可交换性假设，即可为任意代理模型（神经网络、随机森林、GP 等）生成具有覆盖率保证的预测集，在安全关键应用中提供更可信的不确定性边界。",
