          "core_work": "本文提出物理信息高斯过程回归（Pi-GPR）方法，用于粒子追踪测速（PTV）数据的数据同化与不确定性量化。传统 PTV 数据处理依赖插值或平滑，难以融入流体力学的物理约束（如不可压缩条件、N-S 方程）。本文将流体控制方程作为 GP 均值函数的物理先验，并在核函数中嵌入速度-压力耦合的微分算子结构，使得 GP 不仅拟合观测数据，更保证预测满足质量与动量守恒。",
