            "**创新之处**：将 Pi-GP 与 BO 结合用于制造工艺优化：物理信息均值函数使 GP 在小样本条件下仍能捕捉熔池演变的基本规律，避免纯数据驱动模型在样本稀疏时的非物理预测；物理信息核函数进一步将热扩散的空间尺度嵌入协方差，使得预测在参数空间外推时仍保持物理合理性；BO 在此基础上以样本高效的方式搜索最优工艺窗口。",
            "**与您偏好关联**：✅ 物理信息高斯过程（Pi-GPR）✅ 贝叶斯优化 ✅ 物理信息核函数 ✅ 制造工艺优化。与您偏好的物理知识引导 + GP + BO 方向高度吻合，是物理信息代理模型在智能制造中的典型应用。"
