          "abstract": "本文提出了鲁棒计算感知高斯过程（RCaGP），解决了标准 GP 在处理被异常值污染的大规模数据集时的困难。核心洞察是鲁棒性和近似感知不是正交的，而是相互交织的。通过将两者结合在一个可扩展框架中，RCaGP 有效管理异常值和计算不确定性，在干净和异常值污染的数据集上均表现出优越性能。",
          "rank": 5,
          "core_work": "本文提出了鲁棒计算感知高斯过程（Robust Computation-aware Gaussian Process, RCaGP），针对标准 GP 在处理含异常值的大规模数据集时面临的鲁棒性和可扩展性双重挑战。核心创新在于揭示鲁棒性和近似感知之间的内在联系，并将两者统一在一个可扩展的框架中。",
          "contributions": "提出了 RCaGP 框架，将鲁棒性和计算近似感知统一在一个可扩展的 GP 框架中；建立了鲁棒性理论性质，强调均值函数的重要性；在干净和含异常值的数据集上均实现了优越的预测性能。",
          "innovation": "揭示了 GP 的鲁棒性与计算近似之间的内在联系——两者不是正交的而是相互交织的，从而提出了一种同时处理异常值和计算不确定性的统一方法。",
          "relevance": "与用户偏好相关：Gaussian Process + 不确定性量化 + 可扩展性。该工作解决了 GP 在实际工程应用中常见的数据质量问题（异常值）和计算效率问题，发表在 NeurIPS 2025 顶会。",
          "citations": 0,
          "venue_tier": "CCF-A Conference",
          "images": [],
          "content": [
            "",
            "高斯过程因其强大的表达力被广泛用于回归和贝叶斯优化等任务。然而，标准 GP 在两个关键方面存在局限：一是面对含异常值的大规模数据集时缺乏鲁棒性；二是面对大规模数据时计算成本高昂。现有方法通常分别解决这两个问题，忽略了它们之间的关联。",
            "## RCaGP 框架",
            "本文提出的 RCaGP 框架基于一个核心洞察：鲁棒性和计算近似感知不是正交的，而是相互交织的。例如，计算近似引入的不确定性可能放大异常值的影响，而异常值的存在也可能影响近似的质量。RCaGP 通过统一的框架同时管理这两种不确定性。",
            "## 鲁棒性理论",
            "作者建立了 RCaGP 的鲁棒性理论性质，特别强调了均值函数在确保鲁棒预测中的关键作用。这为理解 GP 在异常值存在下的行为提供了理论指导。",
            "## 实验结果",
            "在多个干净和异常值污染的数据集上的实验表明，RCaGP 在预测性能上优于分别处理鲁棒性和可扩展性的现有方法，展示了统一框架的优势。"
          ]
