          "abstract": "本文提出了 BOLT——一种利用大语言模型（LLM）来扩展多任务贝叶斯优化的迁移策略。BOLT 将历史 BO 运行蒸馏到 LLM 中，由 LLM 为新任务提出候选解，而测试时的代理模型仍保持单任务。该方法可扩展到约 1500 个任务而不出现性能饱和。",
