          "code": null,
          "abstract": "本文挑战了长期以来的信念——即标准 GP 的贝叶斯优化在高维问题中表现不佳。通过 12 个基准测试的评估，作者发现平方指数（SE）核常导致问题，而使用 Matérn 核可使标准 BO 持续达到顶级结果。理论上，SE 核的差性能源于长度尺度参数的不当初始化导致的梯度消失。",
          "rank": 7,
          "core_work": "本文系统性地重新评估了标准高斯过程在贝叶斯优化中的表现，挑战了「标准 GP 不适用于高维 BO」的传统观念。通过 12 个基准测试，作者发现问题的根源在于平方指数（SE）核的参数初始化，而非 GP 方法本身的局限。",
          "contributions": "通过 12 个基准测试证明标准 BO 在使用 Matérn 核时可在高维问题中持续达到顶级表现；理论上揭示了 SE 核性能不佳的原因是长度尺度初始化导致的梯度消失；提出了一种简单鲁棒的初始化策略，显著提升了 SE 核的性能。",
          "innovation": "从理论和实验两个层面揭示了高维 BO 中 SE 核失败的根本原因——梯度消失，并提出了一种简单而有效的初始化策略来缓解这一问题，颠覆了「需要复杂方法才能解决高维 BO」的固有认知。",
          "relevance": "与用户偏好高度相关：Gaussian Process + Bayesian Optimization + 高维问题。该工作为基于高斯过程的贝叶斯优化提供了重要的实践指导，发表在 ICLR 2025 顶会，对代理建模和序贯优化具有直接的方法论价值。",
