            "## 研究背景",
            "经典熵搜索类 BO（ES/JES）以「全局最优解位置」的信息增益为采集准则，需要大量评估才能在多峰问题上定位全局盆地。而工程实践中（如仿真校准、控制器调参），往往只关心某个高效迭代优化器从初值出发能下降到的局部最优。",
            "## LES 方法",
